import { Alpha, Beta, Registry } from "class-value-fields-base";

export function exercise() {
  const registry = new Registry();
  const classAlias = registry.Alpha;
  const objectShelf = { Alpha, Beta };
  const objectAlias = objectShelf.Beta;
  return [
    new classAlias().value(),
    classAlias.tag(),
    classAlias === Alpha,
    registry.Beta === Beta,
    registry.Alpha === Beta,
    new objectAlias().value(),
    objectAlias.tag(),
    objectAlias === Beta,
    objectShelf.Alpha === Alpha,
    objectShelf.Alpha === Beta,
  ];
}
